package piglatin

import "strings"

func Sentence(sentence string) string {
	words := strings.Fields(sentence)
	translated := make([]string, len(words))
	for i, w := range words {
		translated[i] = word(w)
	}
	return strings.Join(translated, " ")
}

func isVowel(r rune) bool {
	switch r {
	case 'a', 'e', 'i', 'o', 'u':
		return true
	}
	return false
}

func word(w string) string {
	if w == "" {
		return ""
	}
	// Rule 1: starts with a vowel, or "xr" or "yt"
	if isVowel(w[0]) || (len(w) >= 2 && (w[:2] == "xr" || w[:2] == "yt")) {
		return w + "ay"
	}
	// Find the consonant prefix
	i := 0
	for i < len(w) && !isVowel(w[i]) {
		// Rule 3: "qu" — move the consonants before it and the qu
		if i+1 < len(w) && w[i] == 'q' && w[i+1] == 'u' {
			i += 2
			break
		}
		// Rule 4: y after one or more consonants
		if i > 0 && w[i] == 'y' {
			break
		}
		i++
	}
	return w[i:] + w[:i] + "ay"
}
```

