package piglatin

import "strings"

// Sentence translates a sentence from English to Pig Latin.
func Sentence(sentence string) string {
	words := strings.Fields(sentence)
	for i, w := range words {
		words[i] = word(w)
	}
	return strings.Join(words, " ")
}

func isVowel(c byte) bool {
	switch c {
	case 'a', 'e', 'i', 'o', 'u':
		return true
	}
	return false
}

// word translates a single word to Pig Latin.
func word(w string) string {
	// Rule 1: word begins with a vowel, "xr", or "yt".
	if isVowel(w[0]) || (len(w) >= 2 && (w[:2] == "xr" || w[:2] == "yt")) {
		return w + "ay"
	}

	// Rules 2-4: move the leading consonant cluster to the end.
	i := 0
	for i < len(w) && !isVowel(w[i]) {
		// Rule 3: a "qu" after any consonants moves along with them.
		if w[i] == 'q' && i+1 < len(w) && w[i+1] == 'u' {
			i += 2
			break
		}
		// Rule 4: a "y" after at least one consonant ends the cluster.
		if i > 0 && w[i] == 'y' {
			break
		}
		i++
	}
	return w[i:] + w[:i] + "ay"
}
